parameters.jsCode:
// Parsear respuesta de NVIDIA Llama 3.1
const nvidiaResponse = $input.item.json;
let content = '';
try {
  content = nvidiaResponse.choices[0].message.content || '';
} catch(e) {
  content = JSON.stringify(nvidiaResponse);
}

let analysis = {};
try {
  // Limpiar markdown si viene envuelto
  const cleaned = content
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();
  analysis = JSON.parse(cleaned);
} catch(e) {
  analysis = {
    es_prospecto_real: true,
    score_final: $input.item.json.score || 50,
    nivel_interes_b2b: 'TIBIO',
    zona_prioritaria: false,
    deal_size_estimado: 'Desconocido',
    urgencia_deteccion: 'MEDIA',
    diagnostico_corto: 'Análisis no disponible: ' + content.substring(0, 100),
    accion_recomendada: 'Revisar manualmente el prospecto.',
    script_apertura_wsp: '',
    red_flag: 'Error parsing: ' + e.message
  };
}

// Obtener datos originales del lead (vienen del Split node)
const originalJson = $input.item.json;

return {
  json: {
    // Datos originales del lead
    nombre: originalJson.nombre || '—',
    telefono: originalJson.telefono || 'Ver perfil',
    ubicacion: originalJson.ubicacion || '—',
    superficie: originalJson.superficie || '—',
    precio: originalJson.precio || 'No especificado',
    estado_masterplan: originalJson.estado_masterplan || '—',
    link_perfil: originalJson.link_perfil || '',
    link_post: originalJson.link_post || '',
    fuente: originalJson.fuente || 'Facebook',
    score_original: originalJson.score || 0,
    rank: originalJson.rank || 0,
    // Análisis de Llama
    ...analysis,
    score_final: analysis.score_final || originalJson.score || 0
  }
};

